Object.assign(SNIP,{"h20khuon": "void thu(int i) {\n    if (i == n) {                  // đủ n vị trí: một cấu hình hoàn chỉnh\n        xuLy();\n        return;\n    }\n    for (int v : cacGiaTriHopLe(i)) {\n        x[i] = v;                  // chọn\n        // đánh dấu nếu cần (ví dụ daDung[v] = true)\n        thu(i + 1);                // đi tiếp\n        // hoàn tác đánh dấu (daDung[v] = false)\n    }\n}"});PRESET_NOTES["l20"]={"Ví dụ: Sinh xâu nhị phân": "Cây lời gọi có 2³ = 8 lá, mỗi lá là một xâu, in theo thứ tự từ điển vì thử '0' trước '1'.", "Ví dụ: Sinh hoán vị": "3! = 6 hoán vị. Mảng daDung ngăn một số được dùng hai lần; quên hoàn tác thì chỉ sinh được hoán vị đầu tiên.", "Ví dụ: Tổ hợp chập k": "C(4, 2) = 6 tổ hợp. Bắt phần tử sau lớn hơn phần tử trước để mỗi tập chỉ sinh một lần (1 2 và 2 1 là cùng một tổ hợp)."};EX_HINTS["l20"]=[["Quay lui: vị trí i nhận '0' rồi '1' (thứ tự này cho thứ tự từ điển).", "Chỉ đặt '1' khi i = 0 hoặc x[i − 1] = '0': cắt nhánh ngay, không sinh rồi mới lọc.", "Số xâu là số Fibonacci, với n = 15 chỉ khoảng 1600 xâu."], ["Vị trí i nhận giá trị từ batDau tới n; gọi tiếp với batDau = v + 1.", "Bắt đầu thu(0, 1). Đủ k vị trí thì in.", "Chú ý không có dấu cách thừa cuối dòng."], ["Mỗi gói có hai lựa chọn (A hoặc B): 2ⁿ cách, với n = 20 khoảng một triệu — kịp giờ.", "Đáp án là min |tổng − 2 · sA| trên mọi cách chọn.", "Cắt nhánh: nếu 2 · sA − tổng đã ≥ đáp án tốt nhất hiện có thì thêm gói cho A chỉ làm chênh lệch lớn hơn."]];
