const PR20=[{label:"Ví dụ: Sinh xâu nhị phân",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint n = 3;\nstring x = \"000\";\n\nvoid thu(int i) {\n    if (i == n) { cout << x << \"\\n\"; return; }\n    x[i] = '0';                        // nhánh 0\n    thu(i + 1);\n    x[i] = '1';                        // nhánh 1\n    thu(i + 1);\n}\n\nint main() {\n    thu(0);\n    return 0;\n}",viz:[{type:"calls"},{type:"vars",names:["x"]}]},{label:"Ví dụ: Sinh hoán vị",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint n = 3;\nvector<int> x(3);\nvector<bool> daDung(4, false);\n\nvoid thu(int i) {\n    if (i == n) {\n        for (int v : x) cout << v << \" \";\n        cout << \"\\n\";\n        return;\n    }\n    for (int v = 1; v <= n; v++)\n        if (!daDung[v]) {\n            x[i] = v;\n            daDung[v] = true;          // chọn\n            thu(i + 1);\n            daDung[v] = false;         // hoàn tác\n        }\n}\n\nint main() {\n    thu(0);\n    return 0;\n}",viz:[{type:"cells",of:"x"},{type:"cells",of:"daDung"},{type:"calls"}]},{label:"Ví dụ: Tổ hợp chập k",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint n = 4, k = 2;\nvector<int> x(2);\n\nvoid thu(int i, int batDau) {          // vị trí i nhận giá trị từ batDau trở đi\n    if (i == k) {\n        cout << x[0] << \" \" << x[1] << \"\\n\";\n        return;\n    }\n    for (int v = batDau; v <= n; v++) {\n        x[i] = v;\n        thu(i + 1, v + 1);             // phần tử sau lớn hơn phần tử trước\n    }\n}\n\nint main() {\n    thu(0, 1);\n    return 0;\n}",viz:[{type:"cells",of:"x"},{type:"calls"}]}];
